import {fossilObjects,fossilObject,fossilDetail,fossilTeaching,fossilComparison,fossilScale} from './fossil-close-content.mjs';
import {initialFossil,changeFossil} from './fossil-close-core.mjs';
import {hearButton} from './play-media.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let visit=null,owner=null;
export function resetFossilSession(){visit=null;owner=null;}
export function fossilSession(){return visit?structuredClone(visit):null;}
function current(id){if(owner!==id||!visit){visit=initialFossil();owner=id;}return visit;}
const button=(attrs,label,disabled=false)=>`<button type="button" class="secondary" ${attrs}${disabled?' disabled':''}>${esc(label)}</button>`;
function credit(o){return `<p class="fossil-credit">${esc(o.credit)}<br><a href="${o.url}" target="_blank" rel="noopener noreferrer">Source record and caption</a> · <a href="${o.original}" target="_blank" rel="noopener noreferrer">Complete original photograph</a></p>`;}
function crop(o,d){const [x,y,w,h]=d.rect;return `<div class="fossil-crop" data-fossil-crop="${d.id}" data-fossil-photo="${o.id}" style="aspect-ratio:${o.width*w}/${o.height*h}"><img data-fossil-image src="${o.src}" style="width:${100/w}%;left:${-x/w*100}%;top:${-y/h*100}%" alt="${esc(d.alt)}"></div>`;}
function fallback(o,d){return `<div class="fossil-image-failure" hidden role="status"><p>This photograph is unavailable. Read its description or open its source.</p><p>${esc(d?.alt||o.alt)}</p></div>`;}
function look(s){const o=fossilObject(s.photo),d=fossilDetail(s.photo,s.detail);return `<section aria-labelledby="fossil-view-title"><h2 id="fossil-view-title" tabindex="-1">Look: ${esc(o.title)}</h2><div class="fossil-object-choices">${fossilObjects.map(x=>button(`data-fossil-photo-choice="${x.id}" aria-pressed="${s.photo===x.id}"`,x.button)).join('')}</div><p class="fossil-instruction">Choose a looking detail, then pin it if you want. Compare is always open.</p><div class="fossil-detail-choices">${button(`data-fossil-detail="whole" aria-pressed="${!d}"`,'Whole photograph')}${o.details.map(x=>button(`data-fossil-detail="${x.id}" aria-pressed="${d?.id===x.id}"`,x.label)).join('')}</div><figure class="fossil-figure"><div class="fossil-whole"><img data-fossil-image src="${o.src}" width="${o.width}" height="${o.height}" alt="${esc(o.alt)}">${d?`<div class="fossil-looking-guide" style="left:${d.rect[0]*100}%;top:${d.rect[1]*100}%;width:${d.rect[2]*100}%;height:${d.rect[3]*100}%"></div>`:''}</div>${d?`<p class="fossil-guide-note">Dashed box: our looking guide, not a body outline or measurement.</p>${crop(o,d)}<figcaption>${esc(d.caption)}</figcaption>`:`<figcaption>${esc(o.alt)}</figcaption>`}${fallback(o,d)}</figure><div class="fossil-pin-actions">${button('data-fossil-pin','Pin this visible clue',true)}${s.pins[s.photo]?button(`data-fossil-remove="${s.photo}"`,'Remove this pin'):''}${button('data-fossil-view="compare"','Compare')}</div><p class="fossil-pin-guidance">${d?'The current photograph must finish loading before pinning.':'Choose a detail to pin, or compare without a pin.'}</p>${credit(o)}${button('data-fossil-source',s.sourceOpen?"Hide the source's interpretation":"Reveal the source's interpretation")}${s.sourceOpen?`<aside class="fossil-source"><p>${esc(o.interpretation)}</p><p>${esc(o.context)}</p><p>From the source and science references: not something the photo's color tells us.</p></aside>`:''}</section>`;}
function compare(s){return `<section aria-labelledby="fossil-view-title"><h2 id="fossil-view-title" tabindex="-1">Compare our chosen clues</h2><p class="fossil-scale">${fossilScale}</p><div class="fossil-compare">${fossilObjects.map(o=>{const d=fossilDetail(o.id,s.pins[o.id]);return `<article><h3>${esc(o.title)}: our pinned clue</h3>${d?`${crop(o,d)}<p class="fossil-caption">${esc(d.caption)}</p>${fallback(o,d)}`:'<p>No visible clue pinned yet. Look at this photograph, or keep comparing.</p>'}${credit(o)}<div class="fossil-pin-actions">${button(`data-fossil-back="${o.id}"`,'Back to this photograph')}${d?button(`data-fossil-remove="${o.id}"`,'Remove this pin'):''}</div></article>`;}).join('')}</div><details class="fossil-comparison-help"><summary>What can we say?</summary><p>${fossilComparison}</p></details><details><summary>Talk together</summary><p>Point to a detail you can actually see in each photo. Which words came from looking, and which came from the source? What would you need before drawing a whole living animal?</p></details></section>`;}
function narration(s,help=false,failed=false){const o=fossilObject(s.photo),d=fossilDetail(s.photo,s.detail);if(s.view==='compare')return `Compare our chosen clues. ${fossilObjects.map(x=>`${x.title}: ${fossilDetail(x.id,s.pins[x.id])?.caption||'No visible clue pinned yet. Look at this photograph, or keep comparing.'}`).join(' ')} ${fossilScale}${help?' '+fossilComparison:''}${failed?' A photograph is unavailable. Read its description or open its source.':''}`;return `${o.title}. ${d?d.alt+' '+d.caption:o.alt}${s.sourceOpen?' '+o.interpretation+' '+o.context+' From the source and science references: not something the photo’s color tells us.':''}${failed?' This photograph is unavailable. Read its description or open its source.':''}`;}
export function fossilEntry(){return '<aside class="fossil-entry"><h2>Fossil Close-Look</h2><p>Choose visible clues from two real photographs: a body-form fossil and a preserved footprint.</p><a class="secondary" href="#living/fossils">Look back at past life</a></aside>';}
export function fossilPage(explorerId){const s=current(explorerId);return `<div class="fossil-page"><header class="page-heading"><a class="back" href="#living"><span aria-hidden="true">←</span> Living Garden</a><h1>Fossil Close-Look</h1><p>The nature corner is looking back beyond the town's story. These real photos show two different clues to past life. Look closely, choose a detail, and compare.</p></header><div class="fossil-sheet"><p class="fossil-teaching">${fossilTeaching}</p><details class="fossil-words"><summary>Words to explore</summary><p>Geological deposits: rock or other material laid down in Earth's past.</p><p>Paleontologists study fossils and their setting to learn about past life.</p></details><p class="fossil-model-note">Real source photographs. Our looking guides and clue captions are made for this game.</p><nav class="fossil-turns" aria-label="Open fossil turns">${['look','compare'].map(v=>button(`data-fossil-view="${v}" aria-pressed="${s.view===v}"`,v==='look'?'Look':'Compare')).join('')}</nav>${s.view==='look'?look(s):compare(s)}<p id="fossil-status" tabindex="-1" role="status"></p>${hearButton(narration(s),'Hear this view')}<footer><a href="#living/bodies">Look at living body clues</a><a href="#archive">Visit Travelers' Archive</a><a href="#living">Back to Living Garden</a><p>The living-picture key and the archive ask different questions. This fossil visit does not finish either.</p><details><summary>Sources and picture limits</summary><p>These are photographs from other places, not fossils discovered in the fictional storm. They do not establish the town's geology. No scale, exact age, living color or sound is measured here.</p><a href="https://www.nps.gov/subjects/fossils/what-is-a-fossil.htm" target="_blank" rel="noopener noreferrer">NPS: What is a Fossil?</a><a href="https://www.nhm.ac.uk/schools/teaching-resources/big-ideas-in-science-evolution/trilobite-fossils-resources-and-class-activities.html" target="_blank" rel="noopener noreferrer">Natural History Museum: Trilobite fossils</a><a href="https://www.bgs.ac.uk/discovering-geology/fossils-and-geological-time/trilobites/" target="_blank" rel="noopener noreferrer">British Geological Survey: Trilobites</a><a href="https://www.nps.gov/aboutus/disclaimer.htm" target="_blank" rel="noopener noreferrer">NPS image use policy</a></details></footer></div></div>`;}
export function bindFossil({render,focus,explorerId}){
 const root=document.querySelector('.fossil-page');if(!root)return;
 const capturedOwner=explorerId(),capturedVisit=current(capturedOwner);
 const live=()=>root.isConnected&&document.querySelector('.fossil-page')===root&&location.hash==='#living/fossils'&&explorerId()===capturedOwner&&owner===capturedOwner&&visit===capturedVisit;
 const loaded=()=>[...root.querySelectorAll('[data-fossil-image]')].every(i=>i.complete&&i.naturalWidth>0);
 function syncImages(){if(!live())return;const images=[...root.querySelectorAll('[data-fossil-image]')];for(const box of root.querySelectorAll('.fossil-image-failure')){const container=box.closest('figure,article');box.hidden=![...container.querySelectorAll('[data-fossil-image]')].some(i=>i.complete&&!i.naturalWidth);}const pin=root.querySelector('[data-fossil-pin]');if(pin)pin.disabled=!visit.detail||!loaded();const guidance=root.querySelector('.fossil-pin-guidance');if(guidance&&visit.detail)guidance.textContent=loaded()?'Pin this detail, or choose another looking view.':'The current photograph must finish loading before pinning.';}
 root.querySelectorAll('[data-fossil-image]').forEach(i=>{i.addEventListener('load',syncImages);i.addEventListener('error',syncImages);});syncImages();
 function act(action,value,selector,message=''){if(!live())return;const next=changeFossil(visit,action,value);if(!next)return;visit=next;render();const status=document.querySelector('#fossil-status');if(status)status.textContent=message;focus(selector);}
 root.querySelectorAll('[data-fossil-photo-choice]').forEach(b=>b.addEventListener('click',()=>act('photo',b.dataset.fossilPhotoChoice,'#fossil-view-title')));
 root.querySelectorAll('[data-fossil-view]').forEach(b=>b.addEventListener('click',()=>act('view',b.dataset.fossilView,'#fossil-view-title')));
 root.querySelectorAll('[data-fossil-detail]').forEach(b=>b.addEventListener('click',()=>{if(!live())return;const detail=b.dataset.fossilDetail==='whole'?null:b.dataset.fossilDetail;act('detail',detail,`[data-fossil-detail="${detail||'whole'}"]`,detail?`Looking at: ${fossilDetail(visit.photo,detail)?.label}. This is a closer view of the same photo.`:'Looking at the whole photograph.');}));
 root.querySelector('[data-fossil-pin]')?.addEventListener('click',()=>{if(!live()||!loaded())return;act('pin',null,'#fossil-status',`Pinned one visible clue from the ${visit.photo==='body'?'trilobite':'footprint'} photograph. You can replace or remove it.`);});
 root.querySelectorAll('[data-fossil-remove]').forEach(b=>b.addEventListener('click',()=>act('remove',b.dataset.fossilRemove,'#fossil-status',`The ${b.dataset.fossilRemove==='body'?'trilobite':'footprint'} pin is cleared. Both photographs remain open.`)));
 root.querySelectorAll('[data-fossil-back]').forEach(b=>b.addEventListener('click',()=>act('back',b.dataset.fossilBack,'#fossil-view-title')));
 root.querySelector('[data-fossil-source]')?.addEventListener('click',()=>act('source',null,'[data-fossil-source]'));
 root.querySelectorAll('[data-speak]').forEach(b=>b.addEventListener('click',e=>{if(!live()){e.preventDefault();e.stopImmediatePropagation();return;}b.dataset.speak=narration(visit,!!root.querySelector('.fossil-comparison-help')?.open,[...root.querySelectorAll('.fossil-image-failure')].some(x=>!x.hidden));},{capture:true}));
}
